quests[31833] = { id = 31833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbildung fortsetzen: Meisterin Woo", description = "Willkommen zurück, {name}. Die Zeit ist gekommen, den nächsten Abschnitt Eurer Ausbildung zu absolvieren. Sprecht mit Meisterin Woo unten auf dem Ausbildungsgelände, um Eure nächste Lektion zu erhalten.", sourceObjective = "Sprecht mit Meisterin Woo auf dem Gipfel der Ruhe und schließt Eure Ausbildung mit ihr ab.", completion = "Meisterin Woo hat mir berichtet, dass Eure Ausbildung erfolgreich verlaufen ist. Kehrt zurück, wenn Ihr sie zukünftig fortsetzen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[31834] = { id = 31834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbildung beginnt: Meister Cheng", description = "Seid gegrüßt, {name}. Willkommen auf dem Gipfel der Ruhe. Dies ist der Ort, an dem wir Mönche trainieren und unsere Fertigkeiten in der Kampfkunst perfektionieren. Es ist an der Zeit, dass Ihr Eure Ausbildung antretet. Sprecht mit Meister Cheng auf dem Ausbildungsgelände unter uns, um zu beginnen.", sourceObjective = "Sprecht mit Meister Cheng auf dem Ausbildungsgelände und schließt Eure Ausbildung mit ihm ab.", completion = "Meister Cheng hat mir berichtet, dass Eure Ausbildung erfolgreich verlaufen ist. Kehrt zurück, wenn Ihr sie zukünftig fortsetzen wollt.", sourceObjectiveStatus = "unverified-source-field" }
