quests[31862] = { id = 31862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zonya die Sadistin", description = "Die Beute läuft in das Revier des Raubtiers, ohne sich der Gefahr bewusst zu sein, in der sie sich befindet. Diesmal werdet Ihr Zonya keine Schwierigkeiten bereiten.", sourceObjective = "Besiegt Zonya die Sadistin in einem Haustierkampf.", completion = "Ihr glaubt, Ihr hättet gesiegt, ich werde jedoch mit jeder Niederlage stärker.", sourceObjectiveStatus = "unverified-source-field" }
quests[31870] = { id = 31870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kassandra Kabumm", description = "Kassandra Kabumm ist eine gefürchtete Zähmerin, die vor allem für ihre mechanischen Haustiere bekannt ist. Sie wird die nächste Hürde auf Eurem Weg zum Ruhm darstellen.\n\nFindet sie im Südlichen Brachland in der Nähe von Frazzelcraz' Hauptader und fordert sie heraus. Wenn Ihr Kassandra besiegt, wird das Varzoks Meinung über Euch sicherlich zum Positiven ändern.\n\nViel Glück!", sourceObjective = "Besiegt Kassandra Kabumm in einem Haustierkampf.", completion = "Woah! Ihr habt's echt drauf!", sourceObjectiveStatus = "unverified-source-field" }
quests[31871] = { id = 31871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gluk der Verräter", description = "Ihr habt Gluk schon einmal geschlagen, aber jetzt verpasst Gluk {race} eine Niederlage, weil Ihr so mickrig seid!", sourceObjective = "Besiegt Gluk den Verräter in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31872] = { id = 31872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merda Starkhuf", description = "Genau wie das Land, das immer weiterwächst, ist auch mein Team stärker als je zuvor. Seid Ihr sicher, dass Ihr gegen mich antreten möchtet? Wenn Ihr Euch jetzt geschlagen gebt, ist das keine Schande.", sourceObjective = "Besiegt Merda Starkhuf in einem Haustierkampf.", completion = "Euer Sieg ist wohlverdient. Eure Fertigkeiten sind meinen überlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31876] = { id = 31876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tintenmeister des Arboretums", description = "Ich habe gehört, dass die Tintenmeister im Arboretum die Hilfe eines Schreibers mit den besten Fähigkeiten benötigen. Unterhaltet Euch mit Tintenmeister Wei, wenn Ihr helfen wollt.", sourceObjective = "Sprecht mit Tintenmeister Wei im Arboretum im Jadewald.", completion = "Ah, ein Schreiber mit den besten Fähigkeiten. Einige von uns könnten Eure Hilfe gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31877] = { id = 31877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tintenmeister des Arboretums", description = "Ich habe gehört, dass die Tintenmeister im Arboretum die Hilfe eines Schreibers mit den besten Fähigkeiten benötigen. Unterhaltet Euch mit Tintenmeister Wei, wenn Ihr helfen wollt.", sourceObjective = "Sprecht mit Tintenmeister Wei im Arboretum im Jadewald.", sourceObjectiveStatus = "unverified-source-field" }
quests[31878] = { id = 31878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marlene Trichdie", description = "Ich kann Euch nichts mehr beibringen, {name}. Eure Trainerkarriere jedoch hat gerade erst begonnen!\n\nSucht Marlene Trichdie in Sturmwind auf. Sie steht mit der Elite unter Azeroths Trainern in Verbindung und wird Eurer Entwicklung förderlich sein.", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[31879] = { id = 31879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marlene Trichdie", description = "Ich kann Euch nichts mehr beibringen, {name}. Eure Trainerkarriere jedoch hat gerade erst begonnen!\n\nSucht Marlene Trichdie in Sturmwind auf. Sie steht mit der Elite unter Azeroths Trainern in Verbindung und wird Eurer Entwicklung förderlich sein.", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
