quests[31881] = { id = 31881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marlene Trichdie", description = "Ich kann Euch nichts mehr beibringen, {name}. Eure Trainerkarriere jedoch hat gerade erst begonnen!\n\nSucht Marlene Trichdie in Sturmwind auf. Sie steht mit der Elite unter Azeroths Trainern in Verbindung und wird Eurer Entwicklung förderlich sein.", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[31882] = { id = 31882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varzok", description = "Ich fürchte, es gibt nichts mehr, was ich Euch noch beibringen könnte, {name}. Eure Reise als <Trainer/Trainerin> ist jedoch noch lange nicht zu Ende!\n\nMeldet Euch bei Varzok in Orgrimmar. Er hat Verbindungen zu vielen der besten Trainer von Azeroth und wird Euch dabei helfen, weiter zu wachsen.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31883] = { id = 31883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varzok", description = "Ich fürchte, es gibt nichts mehr, was ich Euch noch beibringen könnte, {name}. Eure Reise als <Trainer/Trainerin> ist jedoch noch lange nicht zu Ende!\n\nMeldet Euch bei Varzok in Orgrimmar. Er hat Verbindungen zu vielen der besten Trainer von Azeroth und wird Euch dabei helfen, weiter zu wachsen.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31884] = { id = 31884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varzok", description = "Ich fürchte, es gibt nichts mehr, was ich Euch noch beibringen könnte, {name}. Eure Reise als <Trainer/Trainerin> ist jedoch noch lange nicht zu Ende!\n\nMeldet Euch bei Varzok in Orgrimmar. Er hat Verbindungen zu vielen der besten Trainer von Azeroth und wird Euch dabei helfen, weiter zu wachsen.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31885] = { id = 31885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varzok", description = "Ich fürchte, es gibt nichts mehr, was ich Euch noch beibringen könnte, {name}. Eure Reise als <Trainer/Trainerin> ist jedoch noch lange nicht zu Ende!\n\nMeldet Euch bei Varzok in Orgrimmar. Er hat Verbindungen zu vielen der besten Trainer von Azeroth und wird Euch dabei helfen, weiter zu wachsen.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31886] = { id = 31886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckensort", description = "Shado-Pan-Bogenschützen halten kontinuierlich Wache über die Schreckensöde, von der Spitze des Schlangenrückens aus. Sie würden die Hilfe von jemand so Fähigem wie Euch, {class}, sicher willkommen heißen.\n\nNehmt einen Drachen und meldet Euch bei Bogenmeisterin Li.", sourceObjective = "Sprecht mit Bogenmeisterin Li auf dem Schlangenrücken.", completion = "Ein Freiwilliger für den Dienst in der Schreckensöde? Da dürftet Ihr der erste sein.\n\nFreut mich, Euch kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31889] = { id = 31889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Kalimdor", description = "Jetzt, da Ihr Gelegenheit hattet, Euren Fertigkeiten den letzten Schliff zu verleihen, steht Euch die Welt der Haustierkämpfe uneingeschränkt offen.\n\nIn Kalimdor gibt es fünf Zähmer, die Ihr für mich besiegen sollt: Gluk den Verräter in Feralas, Grazzel den Großen in den Düstermarschen, Kela Grimmtotem in Tausend Nadeln, Zoltan im Teufelswald und Elena Flatterflug in der Mondlichtung.\n\nWenn Ihr sie bezwingen könnt, seid Ihr bereit, voranzuschreiten.", sourceObjective = "Besiegt Gluk den Verräter, Grazzel den Großen, Kela Grimmtotem, Zoltan und Elena Flatterflug in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31891] = { id = 31891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Kalimdor", description = "Jetzt, da Ihr Gelegenheit hattet, Euren Fertigkeiten den letzten Schliff zu verleihen, steht Euch die Welt der Haustierkämpfe uneingeschränkt offen.\n\nIn Kalimdor gibt es fünf Zähmer, die Ihr für mich besiegen sollt: Gluk den Verräter in Feralas, Grazzel den Großen in den Düstermarschen, Kela Grimmtotem in Tausend Nadeln, Zoltan im Teufelswald und Elena Flatterflug in der Mondlichtung.\n\nWenn Ihr sie bezwingen könnt, seid Ihr bereit, voranzuschreiten.", sourceObjective = "Besiegt Gluk den Verräter, Grazzel den Großen, Kela Grimmtotem, Zoltan und Elena Flatterflug in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31894] = { id = 31894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein empfindliches Gleichgewicht", description = "Zum Shado-Pan berufen zu werden bedeutet, dass man sich dem Schutz des Gleichgewichts und der Harmonie dieses Landes verschreibt. Es ist unsere Pflicht, dieses Gleichgewicht aufrechtzuerhalten, {name}.\n\nDie Aktivitäten der Yaungol in Tonlong jedoch gefährden dieses Gleichgewicht und müssen aufgehalten werden, bevor es zu spät ist.\n\nWir haben Yaungol in den Sumpfbinsen gesichtet. Berichten zufolge sollen sie die Nebellauerer in der Gegend angreifen. Findet heraus warum, und setzt dem ein Ende!", sourceObjective = "Sprecht mit Orbiss in den Sumpfbinsen.", completion = "<Orbiss stöhnt unter Qualen.>\n\nSo so, die Shado-Pan haben Euch ausgesandt, um nachzusehen, was die Yaungol treiben? Nun, seht Ihr es jetzt?", sourceObjectiveStatus = "unverified-source-field" }
quests[31895] = { id = 31895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieber Schrecken als verrecken", description = "Es ist an der Zeit, den Ursprung zu suchen, {name}!\n\nDie Schützen der Shado-Pan halten von der Spitze des Schlangenrückens aus ohne Unterlass Wache über die Schreckensöde. Sie würden die Hilfe von jemandem mit Euren Fähigkeiten als {class} ganz sicher begrüßen.\n\nSucht Bogenmeisterin Li auf dem Schlangenrücken an der Grenze zur Schreckensöde auf.", sourceObjective = "Sprecht mit Bogenmeisterin Li auf dem Schlangenrücken.", completion = "Ein Freiwilliger für den Dienst in der Schreckensöde? Da dürftet Ihr der erste sein.\n\nFreut mich, Euch kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31897] = { id = 31897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Trixxy", description = "Wenn man nach den Meisterzähmern Kalimdors geht, seid Ihr der neue Star der Szene. Warum kommt Ihr nicht bei meinem Ausbildungsgelände in den Eisdistelbergen in Winterquell vorbei, damit ich Euch zeigen kann, wie es wirklich gemacht wird?", sourceObjective = "Besiegt die eiskalte Trixxy in einem Haustierkampf.", completion = "Ihr habt wohl wirklich Starpotenzial, oder? Nächstes Mal wird Euch das Glück weniger hold sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[31902] = { id = 31902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Östliche Königreiche", description = "Jetzt, da Ihr Gelegenheit hattet, Euren Fertigkeiten den letzten Schliff zu verleihen, steht Euch die Welt der Haustierkämpfe uneingeschränkt offen.\n\nIn den Östlichen Königreichen gibt es fünf Zähmer, die Ihr für mich besiegen sollt: David Kosse im Hinterland, Deiza Seuchenhorn in den Östlichen Pestländern, Kortas Düsterhammer in der Sengenden Schlucht, Everessa in den Sümpfen des Elends und Kortas' Bruder Durin Düsterhammer in der Brennenden Steppe.\n\nWenn Ihr sie bezwingen könnt, seid Ihr bereit für den nächsten Schritt.", sourceObjective = "Besiegt David Kosse, Deiza Seuchenhorn, Kortas Düsterhammer, Everessa und Durin Düsterhammer in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31903] = { id = 31903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Östliche Königreiche", description = "Jetzt, da Ihr Gelegenheit hattet, Euren Fertigkeiten den letzten Schliff zu verleihen, steht Euch die Welt der Haustierkämpfe uneingeschränkt offen.\n\nIn den Östlichen Königreichen gibt es fünf Zähmer, die Ihr für mich besiegen sollt: David Kosse im Hinterland, Deiza Seuchenhorn in den Östlichen Pestländern, Kortas Düsterhammer in der Sengenden Schlucht, Everessa in den Sümpfen des Elends und Kortas' Bruder Durin Düsterhammer in der Brennenden Steppe.\n\nWenn Ihr sie bezwingen könnt, seid Ihr bereit für den nächsten Schritt.", sourceObjective = "Besiegt David Kosse, Deiza Seuchenhorn, Kortas Düsterhammer, Everessa und Durin Düsterhammer in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31904] = { id = 31904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kassandra Kabumm", description = "Ich habe meine Haustiere mit neuen gyrotechnischen Ausbildungsmodulen geladen. Ihr seid erledigt!", sourceObjective = "Besiegt Kassandra Kabumm in einem Haustierkampf.", completion = "Ich muss irgendwo eine Zeile falsch umgewandelt haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[31905] = { id = 31905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grazzel der Große", description = "Ihr seid zurück?! Ihr wollt wohl von einem schwarzen Drachen gefressen werden!", sourceObjective = "Besiegt Grazzel den Großen in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31906] = { id = 31906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kela Grimmtotem", description = "Ihr besitzt die Kühnheit, ein Mal mehr Fuß ins Land derer von Grimmtotem zu setzen, um mich herauszufordern? Ihr werdet Euren Entschluss bereuen!", sourceObjective = "Besiegt Kela Grimmtotem in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31907] = { id = 31907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zoltan", description = "Ich werde von Tag zu Tag stärker. Widerstand ist zwecklos.", sourceObjective = "Besiegt Zoltan in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31908] = { id = 31908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elena Flatterflug", description = "Ich sehe schon, Ihr seid bereit für ein weiteres Kräftemessen in den Lüften. Fliegen wir los!", sourceObjective = "Besiegt Elena Flatterflug in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31909] = { id = 31909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Trixxy", description = "Halt! Eure letzte Begegnung hat Euch wohl endlich aufgewärmt, was? Das soll sich ändern.", sourceObjective = "Besiegt die eiskalte Trixxy in einem Haustierkampf.", completion = "Ihr seid wirklich krass drauf!", sourceObjectiveStatus = "unverified-source-field" }
quests[31910] = { id = 31910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "David Kosse", description = "Meine Forschungen haben sich für meine Trainingsmethoden als äußerst nützlich erwiesen. Dieses Mal werde ich Euch besiegen.", sourceObjective = "Besiegt David Kosse in einem Haustierkampf.", completion = "Womöglich ist meine Forschung doch noch nicht so ausgereift, wie ich angenommen hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[31911] = { id = 31911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deiza Seuchenhorn", description = "Noch habt Ihr den wahren Pfad der Untoten nicht eingeschlagen. Vielleicht wird Euch ein weiterer Kampf die Richtung weisen.", sourceObjective = "Besiegt Deiza Seuchenhorn in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31912] = { id = 31912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kortas Düsterhammer", description = "Ich habe gehört, dass Ihr gegen meinen Bruder, diesen Narren, gekämpft habt. Er hat wohl verloren, was?\n\nDann darf ich wohl jetzt zeigen, was ich draufhabe!", sourceObjective = "Besiegt Kortas Düsterhammer in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31913] = { id = 31913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everessa", description = "Ich glaube, ich komme langsam hinter die Geheimnisse dieses Orts... Bald schon werde ich nicht mehr aufzuhalten sein!", sourceObjective = "Besiegt Everessa in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31914] = { id = 31914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durin Düsterhammer", description = "Seit meiner Zeit im Dienst des Feuerlords bin ich für alles gewappnet. Nichts, was Ihr mir entgegenschleudert, könnte mich erschüttern!", sourceObjective = "Besiegt Durin Düsterhammer in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31915] = { id = 31915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Lydia Accoste", description = "Die Meisterzähmer in der Umgebung der Östlichen Königreiche reden schon von Euch. Ihr glaubt, Ihr seid nicht aufzuhalten? Ihr glaubt, dass Ihr <der wahre Großmeister/die wahre Großmeisterin> seid?\n\nDann kommt nur, {name}. Ich erwarte Euch am Gebirgspass der Totenwinde. Kommt, und Ihr werdet die vernichtende Niederlage erleben, die Euch von jeher gebührt.", sourceObjective = "Besiegt Lydia Accoste in einem Haustierkampf.", completion = "Ich habe eine Ewigkeit, um zu trainieren. Ich werde Euch bezwingen!", sourceObjectiveStatus = "unverified-source-field" }
quests[31916] = { id = 31916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeisterin Lydia Accoste", description = "Ihr möchtet mir noch einmal von Angesicht zu Angesicht gegenüberstehen? Diese Entscheidung werdet Ihr bereuen!", sourceObjective = "Besiegt Lydia Accoste in einem Haustierkampf.", completion = "Eure Strategie wird mir immer klarer. Am Ende ist Euch die Niederlage gewiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[31917] = { id = 31917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr des Zähmers", description = "Ihr könnt Euch jetzt kopfüber in waschechte Haustierkämpfe stürz'n. Kehrt zu Eurer Trainerin Marlene Trichdie nach Sturmwind zurück und macht Euch für das Abenteuer Eures Lebens bereit!", sourceObjective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", completion = "Ich bin ja so stolz auf Euch, {name}. Ihr seid zu Großem bereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[31918] = { id = 31918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr des Zähmers", description = "Wenn Ihr mich schlagen könnt, dann seid Ihr bereit für die ganz große Bühne! Sprecht mit Varzok in Orgrimmar.", sourceObjective = "Meldet Euch bei Varzok in Orgrimmar.", completion = "Gut gemacht, {name}. Jetzt könnt Ihr Euch wirklich als Zähmer bezeichnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31919] = { id = 31919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Scherbenwelt", description = "Ihr habt die Meisterzähmer Kalimdors und der Östlichen Königreiche bezwungen, doch Eure nächste Herausforderung wird Euch auf eine sehr viel härtere Probe stellen.\n\nIn der Scherbenwelt gibt es vier Zähmer, die Ihr jetzt besiegen müsst: Nicki Mikrotech auf der Höllenfeuerhalbinsel, Ras'an in den Zangarmarschen, Narrok in Nagrand und Morulu den Älteren in Shattrath.\n\nBesiegt sie, wenn Ihr den Pfad zu wahrer Größe beschreiten wollt.", sourceObjective = "Besiegt Nicki Mikrotech, Ras'an, Narrok und Morulu den Älteren in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31920] = { id = 31920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Antari", description = "Leute wie Euch kenne ich zur Genüge: junge, naive Zähmer, die glauben, dass sie es verdienen, die Siegeslorbeeren auf dem Silbertablett gereicht zu bekommen.\n\nAber nicht mit mir! In mir habt Ihr Euren Meister gefunden, {class}. Ich, Blutritter Antari des Schattenmondtals, kann es kaum erwarten, Euch zu zeigen, wie es sich anfühlt, im Kampf ausgelöscht zu werden.", sourceObjective = "Besiegt Blutritter Antari in einem Haustierkampf.", completion = "Unmöglich! Ich kann nicht verlieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[31921] = { id = 31921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Scherbenwelt", description = "Ihr habt die Meisterzähmer Kalimdors und der Östlichen Königreiche bezwungen, doch Eure nächste Herausforderung wird Euch auf eine sehr viel härtere Probe stellen.\n\nIn der Scherbenwelt gibt es vier Zähmer, die Ihr jetzt besiegen müsst: Nicki Mikrotech auf der Höllenfeuerhalbinsel, Ras'an in den Zangarmarschen, Narrok in Nagrand und Morulu den Älteren in Shattrath.\n\nBesiegt sie, wenn Ihr den Pfad zu wahrer Größe beschreiten wollt.", sourceObjective = "Besiegt Nicki Mikrotech, Ras'an, Narrok und Morulu den Älteren in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31922] = { id = 31922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicki Mikrotech", description = "Meinen Berechnungen zufolge habe ich eine 32,333%-ige Chance zu siegen. Ich werde sie nutzen!", sourceObjective = "Besiegt Nicki Mikrotech in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31923] = { id = 31923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ras'an", description = "Ihr wollt wieder kämpfen? Ich glaube, ich bin besser geworden!", sourceObjective = "Besiegt Ras'an in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31924] = { id = 31924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narrok", description = "Ich möchte noch einmal kämpfen. Diese Grünschnäbel müssen stärker werden.", sourceObjective = "Besiegt Narrok in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31925] = { id = 31925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morulu der Ältere", description = "Seit unserem letzten Aufeinandertreffen habe ich viel gelernt. Wollt Ihr Euer Können erneut auf die Probe stellen?", sourceObjective = "Besiegt Morulu den Älteren in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[31926] = { id = 31926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Antari", description = "Beim letzten Mal habt Ihr aus meinen Fehlern Kapital geschlagen, um den Sieg davonzutragen. Dieses Mal jedoch werdet Ihr weniger Glück haben, {race}.", sourceObjective = "Besiegt Blutritter Antari in einem Haustierkampf.", completion = "Ihr seid töricht, wenn Ihr glaubt, dass Ihr mir überlegen seid. Ich werde Euch zermalmen, das schwöre ich!", sourceObjectiveStatus = "unverified-source-field" }
quests[31927] = { id = 31927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Nordend", description = "Die Besten der Scherbenwelt sind Euren Fertigkeiten zum Opfer gefallen, doch jetzt wartet Nordend auf Euch!\n\nVier Zähmer gilt es zu besiegen: Beegli Lunte im Heulenden Fjord, den fast kopflosen Jakob im Kristallsangwald, Okrut Drachenwüste in der Drachenöde und Darmwürger in Zul'drak.\n\nWenn Ihr über sie alle triumphiert, wird der Großmeister Nordends mit seiner Herausforderung nicht lange auf sich warten lassen!", sourceObjective = "Besiegt Beegli Lunte, den fast kopflosen Jakob, Okrut Drachenwüste und Darmwürger in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[31928] = { id = 31928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmeister Payne", description = "Wenn Ihr mich fragt, haben meine Kollegen bei Eurer Ausbildung viel zu viel Nachsicht walten lassen.\n\nWenn man Haustiere wirklich zähmen will, ist militärische Disziplin gefordert. Ihr werdet die Ehre haben, selbst <Zeuge/Zeugin> dessen zu werden, was solche Disziplin bewirken kann.\n\nKommt zum Argentumturnierplatz in Eiskrone und seht selbst, was Ihr erreichen könntet!", sourceObjective = "Besiegt Major Payne in einem Haustierkampf.", completion = "Ich habe mich in Euch geirrt, {name}. Ihr seid einer der nobelsten Gegner, gegen die ich je die Ehre hatte zu kämpfen. Aber glaubt ja nicht, dass ich Euch beim nächsten Mal auch mit dem Sieg davonkommen lasse!", sourceObjectiveStatus = "unverified-source-field" }
quests[31929] = { id = 31929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfhaustierzähmer: Nordend", description = "Die Besten der Scherbenwelt sind Euren Fertigkeiten zum Opfer gefallen, doch jetzt wartet Nordend auf Euch!\n\nVier Zähmer gilt es zu besiegen: Beegli Lunte im Heulenden Fjord, den fast kopflosen Jakob im Kristallsangwald, Okrut Drachenwüste in der Drachenöde und Darmwürger in Zul'drak.\n\nWenn Ihr über sie alle triumphiert, wird der Großmeister Nordends mit seiner Herausforderung nicht lange auf sich warten lassen!", sourceObjective = "Besiegt Beegli Lunte, den fast kopflosen Jakob, Okrut Drachenwüste und Darmwürger in Haustierkämpfen.", sourceObjectiveStatus = "unverified-source-field" }
